import { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import useDraggable from '../../hooks/useDraggable';
import useSound from '../../hooks/useSound';
import { addRecentDoc } from '../../utils/recentDocs';
import NotepadMenu from './NotepadMenu';
import WindowSystemMenu from '../WindowsSystemMenu';
import NotepadApp from './NotepadApp';
import CriticalError from '../CriticalError';
import OpenModal from '../files/open-modal/OpenModal';
import type { FMItem } from '../files/data/types';
import { TxtIcon } from '../files/data/icons';
import { useFileSystem } from '../../hooks/fileSystemContext';

import NotepadIcon from '../../img/Notepad.webp';
import './Notepad.css';
import '../../App.css';

// import './WindowThemeTest.css'

interface NotepadProps {
    onClose: () => void;
    isMinimized: boolean;
    setIsMinimized: (value: boolean | ((prev: boolean) => boolean)) => void;
    isFullscreen: boolean;
    toggleFullscreen: () => void;
    onMouseDown?: () => void;
    isActive?: boolean;
    initialContent?: string;
    initialFileName?: string;
    globalVolume: number;
    globalMuted: boolean;
    plusTheme?: 'none' | 'aquarium' | 'davinci' | 'nature' | 'space';
    onOpenFM: () => void;
    onError?: (type: import('../CriticalError').ErrorType) => void;
}

const Notepad = ({
    onClose,
    isMinimized,
    setIsMinimized,
    isFullscreen,
    toggleFullscreen,
    onMouseDown,
    isActive,
    initialContent,
    initialFileName,
    globalVolume,
    globalMuted,
    plusTheme,
    onError,
}: NotepadProps) => {
    const { position, handleMouseDown } = useDraggable(400, 150);
    const sounds = useSound(globalVolume, globalMuted);
    const themeSound = plusTheme === 'aquarium' ? sounds.aquarium
        : plusTheme === 'davinci' ? sounds.daVinci
        : plusTheme === 'nature' ? sounds.nature
        : plusTheme === 'space' ? sounds.space
        : null;
    const playExclamation = () => themeSound ? themeSound.playExclamation() : sounds.playExclamation();
    const [showStatusBar, setShowStatusBar] = useState(true);
    const [wordWrap, setWordWrap] = useState(false);
    const [saveAsOpen, setSaveAsOpen] = useState(false);
    const [fileName, setFileName] = useState('Untitled.txt');
    const [savedName, setSavedName] = useState<string | null>(null);
    const [canUndo, setCanUndo] = useState(false);
    const [canRedo, setCanRedo] = useState(false);
    const [pendingAction, setPendingAction] = useState<'new' | 'open' | 'exit' | null>(null);
    const [openModal, setOpenModal] = useState<'about' | 'find' | 'replace' | null>(null);
    const [hasChanges, setHasChanges] = useState(false);
    const [systemMenuOpen, setSystemMenuOpen] = useState(false);
    const { createFile, updateFile } = useFileSystem();
    const [currentItemId, setCurrentItemId] = useState<string | null>(null);

    const persistFile = (name: string, content: string) => {
        const meta = {
            content,
            name,
            size: `${Math.ceil(content.length / 1024) || 1} KB`,
            modified: new Date().toLocaleDateString('en-GB'),
        };
        if (currentItemId) {
            updateFile(currentItemId, meta);
            return currentItemId;
        }
        const newId = `notepad-${Date.now()}`;
        createFile('documents', { id: newId, type: 'file', icon: TxtIcon, ...meta });
        setCurrentItemId(newId);
        return newId;
    };

    // OpenModal (replaces the File Manager picker)
    const [openPickerOpen, setOpenPickerOpen] = useState(false);
    const [localInitialContent, setLocalInitialContent] = useState<string | undefined>(undefined);
    const [localInitialFileName, setLocalInitialFileName] = useState<string | undefined>(undefined);
    const effectiveContent = initialContent ?? localInitialContent;
    const effectiveFileName = initialFileName ?? localInitialFileName;

    const insertDateTimeRef = useRef<() => void>(() => {});

    const textareaRef = useRef<HTMLTextAreaElement>(null);
    const newRef = useRef<() => void>(() => {});
    const undoRef = useRef<() => void>(() => {});
    const redoRef = useRef<() => void>(() => {});
    const actionAfterSaveRef = useRef<'new' | 'open' | 'exit' | null>(null);
    const notepadIconRef = useRef<HTMLImageElement>(null);
    const prevSaveAsOpen = useRef(false);

    const runAction = (action: 'new' | 'open' | 'exit' | null) => {
        if (action === 'exit') onClose();
        else if (action === 'new') { setCurrentItemId(null); newRef.current(); }
        else if (action === 'open') setOpenPickerOpen(true);
    };

    // Load a picked text file's content into the editor via the existing initialContent pipe
    const handleOpenPicked = (item: FMItem) => {
        const content = item.content ?? '';
        setLocalInitialContent(content);
        setLocalInitialFileName(item.name);
        setFileName(item.name);
        setSavedName(item.name);
        setCurrentItemId(item.id);
        setHasChanges(false);
        setOpenPickerOpen(false);
    };

        const handleSaveFromMenu = () => {
        if (savedName) {
            const text = textareaRef.current?.value ?? '';
            persistFile(savedName, text);
            const action = actionAfterSaveRef.current;
            actionAfterSaveRef.current = null;
            setHasChanges(false);
            runAction(action);
        } else {
            setSaveAsOpen(true);
        }
    };

    // Clear deferred action if user cancels Save As without saving
    useEffect(() => {
        if (prevSaveAsOpen.current && !saveAsOpen) {
            actionAfterSaveRef.current = null;
        }
        prevSaveAsOpen.current = saveAsOpen;
    }, [saveAsOpen]);

    // Play exclamation sound when the unsaved-changes dialog opens
    useEffect(() => {
        if (pendingAction) playExclamation();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [pendingAction]);

    // Ctrl+P → print error
    useEffect(() => {
        const handler = (e: KeyboardEvent) => {
            if (e.ctrlKey && e.key === 'p') {
                e.preventDefault();
                onError?.('printerConnect');
            }
        };
        window.addEventListener('keydown', handler);
        return () => window.removeEventListener('keydown', handler);
    }, [onError]);

    //Unsaved changes dialog handlers:
    const handleNew = () => {
        if (hasChanges) { setPendingAction('new'); return; }
        setCurrentItemId(null);
        newRef.current();
    };

    const handleOpen = () => {
        if (hasChanges) { setPendingAction('open'); return; }
        setOpenPickerOpen(true);
    };

    const handleExit = () => {
        if (hasChanges) { setPendingAction('exit'); return; }
        onClose();
    };

    const handleUnsavedYes = () => {
        actionAfterSaveRef.current = pendingAction;
        setPendingAction(null);
        handleSaveFromMenu();
    };

    const handleUnsavedNo = () => {
        const action = pendingAction;
        setPendingAction(null);
        setHasChanges(false);
        runAction(action);
    };

    return (
        <div
            className={[
                'app-window',
                'notepad-window',
                isActive && !openModal && !saveAsOpen && !pendingAction && 'app-window--active',
                isMinimized && 'notepad--minimized',
                isMinimized && 'app-window--minimized',
                isFullscreen && 'notepad--fullscreen',
                isFullscreen && 'app-window--fullscreen',
            ].filter(Boolean).join(' ')}
            style={isFullscreen ? {} : { left: position.x, top: position.y }}
            onMouseDown={onMouseDown}
        >
            <div className='title-bar' onMouseDown={handleMouseDown}>
                <span className='title-bar-text'>
                    <img 
                        className='notepad-icon' 
                        src={NotepadIcon} 
                        alt='MS Notepad Icon'
                        ref={notepadIconRef}
                        onClick={() => setSystemMenuOpen(prev => !prev)} 
                    />
                    {systemMenuOpen && (
                        <WindowSystemMenu
                            open={systemMenuOpen}
                            onRequestClose={() => setSystemMenuOpen(false)}
                            triggerRef={notepadIconRef}
                            isFullscreen={isFullscreen}
                            onRestore={() => toggleFullscreen()}
                            onMove={() => {}}
                            onSize={() => {}}
                            onMinimize={() => setIsMinimized(true)}
                            onMaximize={() => { setIsMinimized(false); toggleFullscreen(); }}
                            onClose={handleExit}
                        />
                    )}
                    {fileName.replace('.txt', '')} - Notepad
                </span>
                <div className='title-bar-buttons xp-title-controls'>
                    <button
                        type='button'
                        className='xp-title-control btn-minimize'
                        onClick={() => setIsMinimized(true)}
                        aria-label='Minimize'
                    >
                        _
                    </button>
                    <button
                        type='button'
                        className={`xp-title-control ${isFullscreen ? 'btn-restore' : 'btn-maximize'}`}
                        onClick={() => {
                            setIsMinimized(false);
                            toggleFullscreen();
                        }}
                        aria-label={isFullscreen ? 'Restore' : 'Maximize'}
                    >
                        {isFullscreen ? '❐' : '□'}
                    </button>
                    <button
                        type='button'
                        className='xp-title-control btn-close'
                        onClick={handleExit}
                        aria-label='Close'
                    >
                        ✕
                    </button>
                </div>
            </div>

            <NotepadMenu
                windowPosition={position}
                showStatusBar={showStatusBar}
                onToggleStatusBar={() => setShowStatusBar(prev => !prev)}
                wordWrap={wordWrap}
                onToggleWordWrap={() => setWordWrap(prev => !prev)}
                textareaRef={textareaRef}
                onSave={handleSaveFromMenu}
                onSaveAs={() => setSaveAsOpen(true)}
                onUndo={() => undoRef.current()}
                onRedo={() => redoRef.current()}
                canUndo={canUndo}
                canRedo={canRedo}
                globalVolume={globalVolume}
                globalMuted={globalMuted}
                plusTheme={plusTheme}
                onError={onError}
                onNew={handleNew}
                onOpen={handleOpen}
                onClose={handleExit}
                onInsertDateTime={() => insertDateTimeRef.current()}
                openModal={openModal}
                setOpenModal={setOpenModal}
            />

            <NotepadApp
                showStatusBar={showStatusBar}
                wordWrap={wordWrap}
                textareaRef={textareaRef}
                newRef={newRef}
                saveAsOpen={saveAsOpen}
                setSaveAsOpen={setSaveAsOpen}
                fileName={fileName}
                setFileName={setFileName}
                onSaveToFileSystem={persistFile}
                onSaved={(name) => {
                    setFileName(name);
                    setSavedName(name);
                    addRecentDoc({ name, path: name, type: 'txt' });
                    const action = actionAfterSaveRef.current;
                    actionAfterSaveRef.current = null;
                    setHasChanges(false);
                    runAction(action);
                    addRecentDoc({ 
                        name, 
                        path: name, 
                        type: 'txt',
                        content: textareaRef.current?.value ?? ''
                    });
                }}
                undoRef={undoRef}
                redoRef={redoRef}
                onHistoryChange={(canUndo, canRedo) => {
                    setCanUndo(canUndo);
                    setCanRedo(canRedo);
                }}
                initialContent={effectiveContent}
                initialFileName={effectiveFileName}
                onChanges={() => setHasChanges(true)}
                insertDateTimeRef={insertDateTimeRef}
            />

            {/* ERROR MODAL */}
            {pendingAction && createPortal(
                <CriticalError
                    type='unsavedChanges'
                    onClose={() => setPendingAction(null)}
                    onYes={handleUnsavedYes}
                    onNo={handleUnsavedNo}
                    onCancel={() => setPendingAction(null)}
                />,
                document.body
            )}

            {/* Open Modal (replaces the FileManager picker) */}
            {openPickerOpen && createPortal(
                <OpenModal
                    title='Open'
                    initialPath={['localdisc', 'c-documents', 'c-admin', 'documents']}
                    fileTypes={[
                        { label: 'Text Documents (*.txt)', extensions: ['.txt'] },
                        { label: 'All Files', extensions: [] },
                    ]}
                    onOpen={handleOpenPicked}
                    onClose={() => setOpenPickerOpen(false)}
                />,
                document.body
            )}
        </div>
    );
};

export default Notepad;